sql.if:
AND EXISTS (
    SELECT 1 FROM customer_info ci
    WHERE ci.id = t.customer_id AND ci.tenant_id = #{ctx.tenantId}
)

mapper.select:
SELECT COUNT(*) FROM company_service t
WHERE t.deleted = 0
  AND t.end_date IS NOT NULL
  AND t.end_date >= #{start}
  AND t.end_date <= #{end}

SELECT COUNT(*) FROM common_task t
WHERE t.deleted = 0
  AND t.create_time >= #{start}
  AND t.create_time <= #{end}

      AND t.status = #{status}

SELECT COUNT(*) FROM common_task t
WHERE t.deleted = 0
  AND t.create_time >= #{start}
  AND t.create_time <= #{end}

SELECT COALESCE(ROUND(AVG(DATEDIFF(t.real_finish_time, DATE(t.create_time))), 2), 0)
FROM common_task t
WHERE t.deleted = 0
  AND t.real_finish_time IS NOT NULL
  AND t.create_time >= #{start}
  AND t.create_time <= #{end}

SELECT COALESCE(t.status, 'UNKNOWN') AS status, COUNT(*) AS count
FROM common_task t
WHERE t.deleted = 0
  AND t.create_time >= #{start}
  AND t.create_time <= #{end}

GROUP BY t.status

SELECT COALESCE(t.star_level, 0) AS starLevel, COUNT(*) AS count FROM cs_customer_profile t WHERE t.deleted = 0
AND t.tenant_id = #{ctx.tenantId}
GROUP BY t.star_level ORDER BY starLevel

SELECT COALESCE(t.bookkeeping_status, '未设置') AS name, COUNT(*) AS count FROM cs_customer_profile t WHERE t.deleted = 0
AND t.tenant_id = #{ctx.tenantId}
GROUP BY t.bookkeeping_status ORDER BY count DESC LIMIT 15

SELECT COALESCE(t.filing_status, '未设置') AS name, COUNT(*) AS count FROM cs_customer_profile t WHERE t.deleted = 0
AND t.tenant_id = #{ctx.tenantId}
GROUP BY t.filing_status ORDER BY count DESC LIMIT 15
